package net.civeira.phylax.feature.observe.observedissue.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueRef;

public interface ObservedIssueQueryRepositoryGateway {

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The items that would be returned by the query
   */
  long count(ObservedIssueFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  boolean exists(String uid, Optional<ObservedIssueFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  Optional<ObservedIssue> find(ObservedIssueFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  List<ObservedIssue> list(ObservedIssueFilter filter);

  /**
   * Retrieve full data for a reference.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param reference a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  ObservedIssue resolve(ObservedIssueRef reference);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  Optional<ObservedIssue> retrieve(String uid, Optional<ObservedIssueFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @param cursor a cursor to order and skip
   * @return The slide with some values
   */
  Slider<ObservedIssue> slide(ObservedIssueFilter filter, ObservedIssueCursor cursor);
}
